<script setup>
const props = defineProps({
  iconId: {
    type: String,
    required: true
  },
  svgClass: {
    type: String,
    default: ''
  }
})

const iconUrl = computed(() => `${import.meta.env.BASE_URL}icons/SvgSprite.svg#${props.iconId}`)
</script>

<template>
  <svg :class="svgClass" v-bind="$attrs">
    <use :href="iconUrl" />
  </svg>
</template>

<style scoped lang="scss">
svg {
  fill: currentColor;
  width: 1em;
  height: 1em;
  display: inline-block;
}
</style>
