<script setup>
import SvgIcon from '@/components/SvgIcon.vue'

const props = defineProps({
  icon: {
    type: String,
    default: ''
  }
})

const isCustom = computed(() => props.icon?.startsWith('pi pi-'))
</script>

<template>
  <template v-if="isCustom">
    <span class="prime-icon" :class="[icon]"></span>
  </template>
  <template v-else>
    <SvgIcon :icon-id="icon"></SvgIcon>
  </template>
</template>

<style scoped lang="scss">
.prime-icon {
  width: 1em;
  height: 1em;
  display: inline-block;
  line-height: 1;
}
</style>
