<script setup>
import DocChatConfig from '@/components/plugins/docChat/DocChatConfig.vue'
import { getKnowledgeList, getDBConfig, getKbPluginSetting } from '@/services/knowledge'
import useKnowledgeStore from '@/stores/knowledge'
import useChatStore from '@/stores/chat'
import { i18nRender } from '@/locales'
import useToastService from '@/hooks/useToastService'

const toast = useToastService()
const kbStore = useKnowledgeStore()

const currentConversationId = ref(useChatStore().currentConversationId)

const dialogVisible = ref(false)
const emit = defineEmits(['kb-selected'])

// 接收预选的知识库ID
const props = defineProps({
  selectedKbName: {
    type: String,
    default: ''
  }
})

const editKbSettingRef = ref()

function openKbSetting() {
  dialogVisible.value = true
}

const kbList = ref([])
function getKbListData() {
  getKnowledgeList({
    name: '',
    page: 1,
    pagesize: 999999
  })
    .then((res) => {
      const result = res.resData
      kbList.value = result.data

      // 如果有预选的知识库ID，则自动选择
      if (props.selectedKbName && !selectedKb.value) {
        console.log('有预选知识库ID:', props.selectedKbName)
        selectedKb.value = props.selectedKbName
        const result = kbList.value.find((kb) => {
          return kb.id === props.selectedKbName
        })
        if (result) {
          handleKbChange({ value: props.selectedKbName })
        }
      }
    })
    .catch((error) => {
      console.error('获取知识库列表失败:', error)
    })
}

const selectedKb = ref('')
const selectedKbData = ref({})
const selectedKbSetting = ref({})
async function handleKbChange({ value }) {
  // 向父组件发送选择的知识库ID
  emit('kb-selected', value)

  const result = kbList.value.find((kb) => {
    return kb.id === value
  })
  selectedKbData.value = Object.assign({}, result)
  kbStore.setKbdata(selectedKbData.value)
  // selectedKbSetting.value = result.config.query_param || {}
  await getKbSetting()
}

function getKbSetting() {
  return getKbPluginSetting({
    kbId: selectedKbData.value.id,
    sessionId: currentConversationId.value,
    plugin_key: 'retrievers'
  }).then((res) => {
    selectedKbSetting.value = res.resData
  })
}

function updateLocalSetting(data) {
  dialogVisible.value = false
  selectedKbSetting.value = Object.assign({}, data)
  getKbListData()
}

const dbConfiged = ref(false)
function checkDBConfig() {
  // chromadb, milvus
  getDBConfig('chromadb').then((res) => {
    const result = res.resData
    if (!result.embed_model) {
      dbConfiged.value = false
      toast.add({ severity: 'warn', summary: i18nRender('kb.warn'), detail: i18nRender('kb.dbConfigWarn'), life: 3000 })
    } else {
      dbConfiged.value = true
      getKbListData()
    }
  })
}

// 组件挂载时初始化
onMounted(() => {
  checkDBConfig()

  // 如果有预选的知识库ID，则设置选中状态
  if (props.selectedKbName) {
    selectedKb.value = props.selectedKbName
  }
})

onUnmounted(() => {
  // 注释掉清空知识库数据的调用，以保持数据持久性
  // kbStore.clearPluginData()
})
</script>

<template>
  <div class="knowledge">
    <div class="kb_config w-full tabs-item">
      <div class="flex justify-between items-center">
        <Dropdown
          v-model="selectedKb"
          :options="kbList"
          optionLabel="name"
          optionValue="id"
          :placeholder="$t('kb.selectKb')"
          checkmark
          class="w-3/5"
          @change="handleKbChange"
        />
        <Button text @click="openKbSetting" :label="$t('lang.config')" v-if="selectedKb" />
      </div>
      <div v-if="selectedKb" class="px-5 space-y-4 mt-4">
        <div class="flex flex-col items-start justify-between">
          <div class="label shrink-0 w-48 text-slate-500 font-bold text-sm mb-2">{{ $t('kb.textCount') }}</div>
          <div class="value text-slate-400 break-all">{{ selectedKbSetting.k }}</div>
        </div>
        <div class="flex flex-col items-start justify-between">
          <div class="label shrink-0 w-48 text-slate-500 font-bold text-sm mb-2">{{ $t('kb.searchType') }}</div>
          <div class="value text-slate-400 break-all">{{ selectedKbSetting.search_type }}</div>
        </div>
        <div class="flex flex-col items-start justify-between" v-if="selectedKbSetting.search_type === 'similarity_score_threshold'">
          <div class="label shrink-0 w-48 text-slate-500 font-bold text-sm mb-2">{{ $t('kb.scoreThreshold') }}</div>
          <div class="value text-slate-400 break-all">{{ selectedKbSetting.score_threshold }}</div>
        </div>
        <div class="flex flex-col items-start justify-between" v-if="selectedKbSetting.search_type === 'mmr'">
          <div class="label shrink-0 w-48 text-slate-500 font-bold text-sm mb-2">{{ $t('kb.fetchK') }}</div>
          <div class="value text-slate-400 break-all">{{ selectedKbSetting.fetch_k }}</div>
        </div>
        <div class="flex flex-col items-start justify-between" v-if="selectedKbSetting.search_type === 'mmr'">
          <div class="label shrink-0 w-48 text-slate-500 font-bold text-sm mb-2">{{ $t('kb.lambdaMult') }}</div>
          <div class="value text-slate-400 break-all">{{ selectedKbSetting.lambda_mult }}</div>
        </div>
        <div class="flex flex-col items-start justify-between">
          <div class="label shrink-0 w-48 text-slate-500 font-bold text-sm mb-2">{{ $t('kb.propmtTemplate') }}</div>
          <div class="value text-slate-400 break-all">{{ selectedKbSetting.prompt_template }}</div>
        </div>
      </div>
    </div>
    <Dialog v-model:visible="dialogVisible" modal :header="$t('kb.kbSetting')" style="width: 600px" @hide="dialogVisible = false">
      <DocChatConfig
        ref="editKbSettingRef"
        :sessionId="currentConversationId"
        :kbId="selectedKbData.id"
        type="retrievers"
        @success="updateLocalSetting"
        @hide="dialogVisible = false"
      />
    </Dialog>
  </div>
</template>

<style scoped lang="scss">
.tabs-item {
  top: 50px;
  width: 260px;
  left: -28px;
  flex-direction: column;
  display: flex;
  align-items: left;
  justify-content: left;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
</style>
