<script setup>
import usePluginsStore from '@/stores/plugins'
import { getCodeAnalysisRecommendList } from '@/services/plugins'

const PluginsStore = usePluginsStore()

const isOpen = computed(() => PluginsStore.codeAnalysisOpen)

const recommendsList = ref([])

function getData() {
  return getCodeAnalysisRecommendList().then((res) => {
    recommendsList.value = res
    return res
  })
}

getData()

const emits = defineEmits(['useRecommend'])

function useRecommend(recommend) {
  emits('useRecommend', recommend)
}
</script>

<template>
  <div v-if="isOpen" class="code-analysis w-full py-2 px-8 bg-slate-100">
    <div class="flex items-center justify-between">
      <div class="recommends-list flex w-full flex-wrap divide-x divide-solid divide-slate-300">
        <div
          class="text-slate-500 text-sm border-clear px-4 cursor-pointer my-2"
          v-for="(item, index) in recommendsList"
          :key="index"
          @click="useRecommend(item)"
        >
          {{ item }}
        </div>
      </div>
      <div class="action shrink-0 grow-0">
        <Button icon="pi pi-refresh" text @click="getData"></Button>
      </div>
    </div>
  </div>
</template>

<style scoped lang="scss"></style>
