<script setup>
import { getRecommendList as service_getRecommendList } from '@/services/chat'
import useModelStore from '../../../stores/models'
import bus from 'vue3-eventbus'

const ModelStore = useModelStore()

const emits = defineEmits(['useRecommend'])

const recommendList = ref([])

function getRecommendList() {
  return service_getRecommendList().then((res) => {
    recommendList.value = res
  })
}

getRecommendList()

function useRecommend(content) {
  emits('useRecommend', content)
}

const baseUrl = computed(() => import.meta.env.BASE_URL)

const loadedModel = computed(() => ModelStore.loadedModel)

const DEFAULT_AVATAR =
  'data:image/png;base64,'

function showWhatsNew() {
  bus.emit('showWhatsNew')
}
</script>

<template>
  <div class="welcome w-full h-full dark:bg-slate-800 flex flex-col items-center justify-center mx-auto relative gap-6">
    <img class="w-28 h-28 rounded-full bg-transparent" :src="loadedModel?.model_pic || DEFAULT_AVATAR" alt="" />
    <div class=""></div>
    <Button rounded severity="info" @click="showWhatsNew">
      <div class="text-center flex items-center justify-center gap-2">
        <img class="w-4 h-4" :src="`${baseUrl}image/app/star.svg`" alt="" />
        <span>点击查看OpenChat功能</span>
      </div>
    </Button>
    <div class="text-xl text-zinc-500">有什么需要帮助的？</div>
    <!--    <Button severity="contrast" label="设置API密钥" rounded @click="showApiKeys"></Button>-->
    <div class="flex flex-row items-center justify-center gap-2">
      <Button
        v-for="item in recommendList"
        :key="item"
        severity="secondary"
        outlined
        rounded
        :label="item"
        @click="useRecommend(item)"
      ></Button>
    </div>
  </div>
</template>

<style scoped lang="scss"></style>
