import request from '@/hooks/useHttp'
import { getRandomElements } from '@/utils/util'

const baseUrl = import.meta.env.BASE_URL

export function getPluginList(data) {
  return request({
    method: 'post',
    url: '/plugin/session/getlist',
    data
  })
}

export function setPluginStatus(data) {
  return request({
    method: 'post',
    url: '/plugin/session/update',
    data
  })
}

export function getPluginStatus(data) {
  return request({
    method: 'post',
    url: '/plugin/get',
    data
  })
}

// 返回的推荐问题数量
const RECOMMENDS_COUNT = 4

export function getCodeAnalysisRecommendList() {
  return fetch(`${baseUrl}code-analysis-recommends.json`)
    .then((res) => res.json())
    .then((data) => {
      return getRandomElements(data, RECOMMENDS_COUNT)
    })
}

