import { defineStore } from 'pinia'
import useChatStore from './chat'

const useKnowledgeStore = defineStore('knowledge', () => {
  const selectedKb = ref({})

  function setKbdata(data) {
    selectedKb.value = Object.assign({}, data)
  }

  const viewFileFlag = ref(false)
  const fileInfo = ref({})

  function setFileView(value) {
    viewFileFlag.value = value
  }

  function setFileInfo(data) {
    fileInfo.value = Object.assign({}, data)
  }

  function getKbData() {
    return {
      knowledge_id: selectedKb.value.id,
      knowledge_name: selectedKb.value.name
    }
  }

  function getChatFileData() {
    if (fileInfo.value.id) {
      return [
        {
          knowledge_id: useChatStore().currentConversationId,
          file_id: fileInfo.value.id,
          file_name: fileInfo.value.name
        }
      ]
    } else {
      return []
    }
  }

  function clearPluginData() {
    selectedKb.value = {}
    fileInfo.value = {}
  }

  return {
    selectedKb,
    setKbdata,
    viewFileFlag,
    fileInfo,
    setFileView,
    setFileInfo,
    getKbData,
    getChatFileData,
    clearPluginData
  }
})

export default useKnowledgeStore
