import { defineStore } from 'pinia'
import { getPluginList as service_getPluginList, getPluginStatus, setSessionPluginStatus } from '../services/plugins'
// import Knowledge from '@/components/plugins/knowleges.vue'
// import CodeAnalysis from '@/views/chat/components/plugins/CodeAnalysis.vue'
// import WebSearch from '@/components/plugins/websearch/WebSearch.vue'
import useChatStore from '@/stores/chat'

const usePluginsStore = defineStore('plugins', () => {
  // const localPlugins = ref([
  //   {
  //     name: 'webSearch',
  //     apiKey: 'preprocess_web_argument',
  //     icon: 'pi-globe',
  //     open: false,
  //     optionComponent: markRaw(WebSearch),
  //     label: 'lang.webSearch',
  //     hasSetting: true
  //   },
  //   // {
  //   //   name: 'knowledge',
  //   //   apiKey: 'retrievers',
  //   //   icon: 'pi-book',
  //   //   open: false,
  //   //   optionComponent: markRaw(Knowledge),
  //   //   label: 'kb.knowledgeBase'
  //   // }
  //   // {
  //   //   name: 'codeAnalysis',
  //   //   apiKey: 'longcode',
  //   //   icon: 'pi-code',
  //   //   open: false,
  //   //   optionComponent: CodeAnalysis,
  //   //   label: 'lang.codeAnalysis'
  //   // }
  // ])

  // const codeAnalysisOpen = computed(() => {
  //   return localPlugins.value.find((item) => item.name === 'codeAnalysis')?.open || false
  // })

  const ChatStore = useChatStore()

  const conversationId = computed(() => ChatStore.currentConversationId)

  const pluginList = ref([])

  function getSessionPluginList() {
    if (!conversationId.value) {
      return
    }
    const params = {
      session_id: conversationId.value, //必填项，session的ID
      plugin_type: 'normal', //必填项，插件类型，默认"normal"
      status: true, //必填项，插件状态，默认true
      search_type: 'one_type_status_nopost' //必填项，查找类型，默认"one_type_status"
    }
    return service_getPluginList(params).then((res) => {
      const { resData } = res
      pluginList.value = resData
    })
  }

  watch(
    () => conversationId.value,
    async (value) => {
      if (value) {
        await getSessionPluginList()
      }
    },
    {
      immediate: true
    }
  )

  function changePluginStatus(plugin, status) {
    const data = pluginList.value.map((item) => ({
      session_id: conversationId.value, //必填项，session的ID
      plugin_id: item.plugin_id, //必填项，插件ID
      update_val: {
        //必填项，要更新的字段
        session_status: item.plugin_id === plugin.plugin_id ? status : false //必填项，插件状态（开启：true; 关闭：false）
      }
    }))
    return setSessionPluginStatus(data)
  }

  function getPlugin(pluginName) {
    return getPluginStatus({ pluginName }).then((res) => {
      return res.resData
    })
  }

  function getLocalPluginStatus(pluginKey) {
    return pluginList.value.find((item) => item.plugin_key === pluginKey)?.session_status || false
    // return localPlugins.value.find((item) => item.name === pluginName)?.open || false
  }

  return {
    pluginList,
    getSessionPluginList,
    changePluginStatus,
    getPlugin,
    getLocalPluginStatus
    // codeAnalysisOpen
  }
})

export default usePluginsStore
