<script setup>
import useModelStore from '@/stores/models'
import Number from '@/views/chat/components/modelParams/inputs/Number.vue'
import Boolean from '@/views/chat/components/modelParams/inputs/Boolean.vue'
import Textarea from '@/views/chat/components/modelParams/inputs/Textarea.vue'
import Text from '@/views/chat/components/modelParams/inputs/Text.vue'
import useChatStore from '@/stores/chat'

const ModelStore = useModelStore()
const ChatStore = useChatStore()

const loadedModel = computed(() => ModelStore.loadedModel)
const loadedModelId = computed(() => loadedModel.value?.id || '')

const modelParamsConfig = ref([])
const params = reactive({})

async function initParams() {
  modelParamsConfig.value = await ModelStore.getModelParamsConfig(loadedModelId.value, ChatStore.currentConversationId)
  modelParamsConfig.value?.forEach((item) => {
    if (item.arg_name) {
      switch (item.arg_datatype) {
        case 'number':
          params[item.arg_name] = +item.arg_value
          break
        case 'bool':
        default:
          // params[item.arg_name] = item.arg_value
          params[item.arg_name] = 'False'
          break
      }
    }
  })

  watch(
    () => params,
    async (val) => {
      await ModelStore.setModelParams(loadedModelId.value, val, ChatStore.currentConversationId)
    },
    { deep: true }
  )
  return params
}

watch(
  () => loadedModelId.value,
  async (val) => {
    if (val) {
      if (ChatStore.currentConversationId) {
        await initParams()
      }
    }
  },
  { immediate: true }
)

const InputComponentMap = {
  number: Number,
  bool: Boolean,
  textarea: Textarea,
  string: Text
}
</script>

<template>
  <div class="model-params space-y-4">
    <div class="flex flex-col items-center justify-center pt-32" v-if="!loadedModelId">
      <i class="pi pi-box text-3xl text-slate-500 mb-4"></i>
      <div class="text-slate-500 text-xl">{{ $t('lang.noModel') }}</div>
    </div>
    <template v-else>
      <div class="form_item" v-for="item in modelParamsConfig" :key="item.arg_name">
        <label for="maxLength" class="text-slate-500 font-bold text-sm">{{ item.arg_name }}</label>
        <div class="flex flex-row items-center justify-start mt-1 space-x-4">
          <component :is="InputComponentMap[item.arg_datatype]" v-model="params[item.arg_name]" :config="item"></component>
        </div>
      </div>
    </template>
  </div>
</template>

<style scoped lang="scss"></style>
