<script setup>
import usePluginsStore from '../../../stores/plugins'
import useChatStore from '../../../stores/chat'
import useAgentStore from '@/stores/agents'
import { ref, computed, watch, defineAsyncComponent, onMounted } from 'vue'

const ChatStore = useChatStore()
const AgentStore = useAgentStore()
const PluginStore = usePluginsStore()
const assistantInfo = ref(null)

const pluginsList = computed(() => (PluginStore.pluginList || []).filter((item) => item.session_status))

const PluginComponents = {
  preprocess_sensitive_filter: defineAsyncComponent(() => import('../../../components/plugins/sensitive/Sensitive.vue')),
  preprocess_web_argument: defineAsyncComponent(() => import('../../../components/plugins/websearch/WebSearch.vue')),
  retrievers: defineAsyncComponent(() => import('../../../components/plugins/knowledgeBase/knowledges.vue')),
  chat_files_retrievers: defineAsyncComponent(() => import('../../../components/plugins/docChat/DocChat.vue')),
  longcode: defineAsyncComponent(() => import('../../../components/plugins/CodeAnalysis.vue'))
}

async function initPlugins() {
  await PluginStore.getSessionPluginList()
}

async function loadAssistantInfo() {
  if (ChatStore.currentConversationId) {
    assistantInfo.value = await AgentStore.fetchAssistant(ChatStore.currentConversationId)
    console.log('Plugins: 加载助手信息:', assistantInfo.value)
  }
}

onMounted(async () => {
  await initPlugins()
  await loadAssistantInfo()
})

// 监听会话变化
watch(
  () => ChatStore.currentConversationId,
  async () => {
    console.log('Plugins: 会话ID变更，重新加载助手信息')
    await loadAssistantInfo()
  }
)

const componentRef = {}

const setRefMap = (el, item) => {
  if (el) {
    componentRef[`${item.name}`] = el
  }
}

// function pluginSetting(plugin) {
//   componentRef[plugin.name].setConfig()
// }
</script>

<template>
  <div
    class="setting_container shadow-md rounded-3xl h-full shrink grow bg-transparent dark:bg-slate-800 p-4 flex flex-col items-start justify-start"
  >
    <!-- <div class="shrink grow label text-xl font-extrabold text-slate-700 dark:text-slate-300 my-2">
      {{ $t('lang.plugin') }}
    </div> -->
    <div class="settings w-full h-full grow shrink space-y-4 mt-6 overflow-y-auto px-3 pb-2">
      <template v-if="pluginsList.length">
        <div class="" v-for="item in pluginsList" :key="item.plugin_id">
          <Divider align="left" class="mb-4">
            <span class="font-bold text-lg title-items">{{ item.plugin_name }}</span>
          </Divider>
          <div class="plugin-component px-5">
            <component
              :key="ChatStore.currentConversationId"
              :ref="(el) => setRefMap(el, item)"
              :is="PluginComponents[item.plugin_key]"
              :plugin-id="item.plugin_id"
              :selected-kb-name="item.plugin_key === 'retrievers' && assistantInfo ? assistantInfo.kb : ''"
            ></component>
          </div>
        </div>
      </template>
      <template v-else>
        <div class="flex flex-col items-center justify-center pt-32" v-if="!loadedModelId">
          <i class="pi pi-box text-3xl text-slate-500 mb-4"></i>
          <div class="text-slate-500 text-xl">{{ $t('lang.noPluginOpen') }}</div>
        </div>
      </template>
    </div>
  </div>
</template>

<style scoped lang="scss">
.title-items {
  position: absolute;
  top: -10px;
  left: -10px;
  display: flex;
  flex-direction: row;
  z-index: 10;
  padding-top: 20px;
}
</style>
