<script setup>
import { ref, reactive, onMounted, inject } from 'vue'
import bus from 'vue3-eventbus'
import useToastService from '@/hooks/useToastService'
import { i18nRender } from '@/locales'
import useAgentStore from '@/stores/agents'
import useChatStore from '@/stores/chat'
import useAgentsStore from '@/stores/agents'
import usePluginsStore from '@/stores/plugins'
import Dropdown from 'primevue/dropdown'
import TabView from 'primevue/tabview'
import TabPanel from 'primevue/tabpanel'
import MultiSelect from 'primevue/multiselect'

// 导入知识库组件
import KnowledgeComponent from '@/components/plugins/knowledgeBase/knowledges.vue'
//导入MCP Settings组件
import MCPSettings from '@/views/chat/components/AssistantMCPSettings.vue'

// 获取对话框引用
const dialogRef = inject('dialogRef')
const AgentStore = useAgentStore()
const ChatStore = useChatStore()
const toast = useToastService()
const agentsStore = useAgentsStore()
const pluginsStore = usePluginsStore()

// 获取base URL
const baseUrl = import.meta.env.BASE_URL

// 预设的头像路径列表
const DEFAULT_AVATAR_PATHS = [`${baseUrl}icons/icon/ai-technology (1).png`, `${baseUrl}icons/icon/ai-technology (2).png`]

// 默认头像
const DEFAULT_AVATAR = DEFAULT_AVATAR_PATHS[0]

// 预设的分类
const AGENT_CATEGORIES = [
  { label: '开发', value: 'development' },
  { label: '营销', value: 'marketing' },
  { label: '教育', value: 'education' },
  { label: '文化', value: 'culture' },
  { label: '工具', value: 'tools' },
  { label: '写作', value: 'writing' },
  { label: '职业', value: 'job' },
  { label: '娱乐', value: 'entertainment' },
  { label: '心理', value: 'mental_health' },
  { label: '其他', value: 'normal' }
]

// 表单数据
const form = ref({
  name: '',
  prompt: '',
  welcome_message: '',
  recommended_questions: [],
  description: '',
  category: [],
  avatar: DEFAULT_AVATAR,
  kb: '' // 添加kb字段
})

// 选项卡激活状态
const activeTabIndex = ref(0)

// 表单错误状态和加载状态
const formErrors = reactive({
  name: '',
  prompt: ''
})
const loading = ref(false)

// 会话和助手ID
const assistantId = ref('')

// 验证名称
function validateName() {
  if (!form.value.name) {
    formErrors.name = i18nRender('assistant.missingName')
    return false
  }
  formErrors.name = ''
  return true
}

// 验证提示词
function validatePrompt() {
  if (!form.value.prompt) {
    formErrors.prompt = i18nRender('assistant.missingPrompt')
    return false
  }
  formErrors.prompt = ''
  return true
}

// 选择头像
function selectAvatar(avatar) {
  form.value.avatar = avatar
}

// 初始化表单数据
onMounted(async () => {
  // 获取助手数据：优先从对话框数据获取，否则尝试从Store获取
  let assistantData = null

  if (dialogRef?.value?.data?.assistant) {
    // 从对话框数据获取
    assistantData = dialogRef.value.data.assistant
    assistantId.value = assistantData.id
  } else {
    // 从Store获取当前会话的助手数据
    const currentSessionId = ChatStore.currentConversationId
    if (currentSessionId) {
      assistantData = await AgentStore.fetchAssistant(currentSessionId)
      if (assistantData) {
        assistantId.value = assistantData.id
      }
    }
  }

  // 填充表单
  if (assistantData) {
    console.log('加载会话助手数据:', assistantData)
    form.value = {
      id: assistantData.id || '',
      name: assistantData.name || '',
      prompt: assistantData.prompt || '',
      welcome_message: assistantData.welcome_message || '',
      recommended_questions: assistantData.recommended_questions || [],
      description: assistantData.description || '',
      category: assistantData.category || ['normal'],
      avatar: assistantData.avatar || DEFAULT_AVATAR,
      kb: assistantData.kb || ''
    }

    // 确保 recommended_questions 始终是数组
    if (!Array.isArray(form.value.recommended_questions)) {
      form.value.recommended_questions = []
    }
  }
})

// 添加推荐问题
function addQuestion() {
  form.value.recommended_questions.push('')
}

// 删除推荐问题
function removeQuestion(index) {
  form.value.recommended_questions.splice(index, 1)
}

// 当知识库选择变化时更新form中的kb字段
function handleKnowledgeSelected(kbId) {
  console.log('选择的知识库ID:', kbId)
  form.value.kb = kbId
}

// 启用知识库插件函数
async function enableKnowledgePlugin() {
  try {
    // 只有在选择了知识库时才启用插件
    if (!form.value.kb) {
      return
    }

    // 获取知识库插件
    const pluginList = pluginsStore.pluginList
    const knowledgePlugin = pluginList.find((plugin) => plugin.plugin_key === 'retrievers')

    if (knowledgePlugin) {
      console.log('启用知识库插件:', knowledgePlugin.plugin_name)
      // 如果插件未启用，则启用它
      if (!knowledgePlugin.session_status) {
        await pluginsStore.changePluginStatus(knowledgePlugin, true)
        await pluginsStore.getSessionPluginList()
      }
    } else {
      console.warn('未找到知识库插件')
    }
  } catch (error) {
    console.error('启用知识库插件失败:', error)
  }
}

// 保存设置
async function saveSettings() {
  try {
    // 表单验证
    const nameValid = validateName()
    const promptValid = validatePrompt()

    if (!nameValid || !promptValid) {
      return
    }

    loading.value = true

    // 准备更新数据
    const updateVal = {
      ...form.value,
      // 过滤掉空的推荐问题
      recommended_questions: form.value.recommended_questions.filter((q) => q.trim() !== '')
    }

    console.log('准备通过事件总线发送的数据:', {
      assistantId: assistantId.value,
      updateVal
    })
    console.log('updateVal数据JSON:', JSON.stringify(updateVal))

    // 更新助手数据
    bus.emit('assistant:update', { assistantId: assistantId.value, updateVal })

    // 启用知识库插件（如果选择了知识库）
    await enableKnowledgePlugin()

    // 显示成功消息
    toast.add({
      severity: 'success',
      summary: '更新成功',
      detail: '会话助手更新成功',
      life: 3000
    })

    // 关闭对话框
    if (dialogRef?.value) {
      dialogRef.value.close()
    }
  } catch (error) {
    console.error('保存会话助手设置失败:', error)
    toast.add({
      severity: 'error',
      summary: '操作失败',
      detail: error.message || '更新会话助手失败',
      life: 3000
    })
  } finally {
    loading.value = false
  }
}

// 保存到智能体
async function saveToAgent() {
  try {
    // 表单验证
    const nameValid = validateName()
    const promptValid = validatePrompt()

    if (!nameValid || !promptValid) {
      return
    }

    loading.value = true

    // 处理头像路径，移除baseUrl前缀
    let avatarPath = form.value.avatar
    if (avatarPath.startsWith(baseUrl)) {
      avatarPath = avatarPath.substring(baseUrl.length)
    }

    // 准备数据
    const agentData = {
      name: form.value.name,
      prompt: form.value.prompt,
      description: form.value.description,
      welcome_message: form.value.welcome_message,
      recommended_questions: form.value.recommended_questions.filter((q) => q.trim() !== ''),
      category: form.value.category,
      avatar: avatarPath,
      creator_id: 'user', // 默认值，实际上后端会从header中获取
      kb: form.value.kb // 添加kb字段
    }

    // 调用创建接口
    const response = await agentsStore.createAgent(agentData)
    if (response && response.flag === true) {
      toast.add({
        severity: 'success',
        summary: '保存成功',
        detail: '已成功保存为智能体',
        life: 3000
      })

      // 关闭对话框
      if (dialogRef?.value) {
        dialogRef.value.close()
      }
    } else {
      throw new Error(response?.errMsg || '保存智能体失败')
    }
  } catch (error) {
    console.error('保存智能体失败:', error)
    toast.add({
      severity: 'error',
      summary: '保存失败',
      detail: error.message || '保存智能体失败，请重试',
      life: 3000
    })
  } finally {
    loading.value = false
  }
}
</script>

<template>
  <div class="assistant-manager">
    <TabView v-model:activeIndex="activeTabIndex" class="w-full h-full">
      <!-- 基本设置页签 -->
      <TabPanel header="基本设置">
        <div class="form-container">
          <div class="mb-6">
            <label class="block text-normal font-medium text-gray-700 mb-2">{{ $t('assistant.name') }}</label>
            <InputText
              v-model="form.name"
              class="w-full text-normal leading-relaxed"
              :class="{ 'p-invalid': formErrors.name }"
              @blur="validateName"
              placeholder="Assistant Name"
            />
            <small v-if="formErrors.name" class="p-error block mt-1 text-xs leading-5">{{ formErrors.name }}</small>
          </div>

          <div class="mb-6">
            <label class="block text-normal font-medium text-gray-700 mb-2">{{ $t('assistant.prompt') }}</label>
            <Textarea
              v-model="form.prompt"
              class="w-full text-normal leading-relaxed"
              rows="4"
              :class="{ 'p-invalid': formErrors.prompt }"
              @blur="validatePrompt"
            />
            <small v-if="formErrors.prompt" class="p-error block mt-1 text-xs leading-5">{{ formErrors.prompt }}</small>
          </div>

          <div class="mb-6">
            <label class="block text-normal font-medium text-gray-700 mb-2">{{ $t('assistant.welcomeMessage') }}</label>
            <Textarea v-model="form.welcome_message" class="w-full text-normal leading-relaxed" rows="3" />
          </div>

          <div class="mb-6">
            <label class="block text-normal font-medium text-gray-700 mb-2">{{ $t('assistant.recommendedQuestions') }}</label>
            <div class="space-y-3">
              <div v-for="(question, index) in form.recommended_questions" :key="index" class="flex gap-2">
                <InputText
                  v-model="form.recommended_questions[index]"
                  class="flex-1 text-normal leading-relaxed"
                  :placeholder="$t('assistant.questionPlaceholder')"
                />
                <Button
                  icon="pi pi-trash"
                  severity="danger"
                  text
                  @click="removeQuestion(index)"
                  :aria-label="$t('assistant.removeQuestion')"
                />
              </div>
              <Button icon="pi pi-plus" text @click="addQuestion" :label="$t('assistant.addQuestion')" class="text-normal" />
            </div>
          </div>

          <div class="mb-6">
            <label class="block text-normal font-medium text-gray-700 mb-2">{{ $t('assistant.description') }}</label>
            <Textarea v-model="form.description" class="w-full text-normal leading-relaxed" rows="3" />
          </div>

          <div class="mb-6">
            <label class="block text-normal font-medium text-gray-700 mb-2">{{ $t('assistant.category') }}</label>
            <MultiSelect
              v-model="form.category"
              :options="AGENT_CATEGORIES"
              optionLabel="label"
              optionValue="value"
              :placeholder="$t('assistant.selectCategory')"
              class="w-full text-normal leading-relaxed"
              :maxSelectedLabels="3"
              display="chip"
            />
          </div>

          <div class="mb-6">
            <label class="block text-normal font-medium text-gray-700 mb-2">{{ $t('assistant.avatar') }}</label>
            <div class="avatar-selector mt-2">
              <div
                v-for="(avatar, index) in DEFAULT_AVATAR_PATHS"
                :key="index"
                class="avatar-option"
                :class="{ selected: form.avatar === avatar }"
                @click="selectAvatar(avatar)"
              >
                <img :src="avatar" alt="头像选项" />
              </div>
            </div>
          </div>
        </div>
      </TabPanel>

      <!-- 知识库设置页签 -->
      <TabPanel header="知识库设置">
        <div class="kb-settings-container">
          <KnowledgeComponent @kb-selected="handleKnowledgeSelected" :selected-kb-name="form.kb" />
        </div>
      </TabPanel>
      <!-- MCP设置页签 -->
      <!-- <TabPanel header="MCP设置">
        <div class="mcp-settings-container">
          <MCPSettings />
        </div>
      </TabPanel> -->
    </TabView>

    <div class="actions-container">
      <Button
        :label="$t('assistant.cancel')"
        text
        @click="
          () => {
            console.log('取消按钮被点击')
            if (dialogRef) {
              console.log('尝试使用dialogRef直接关闭对话框')
              dialogRef.close()
              return
            }
            console.log('dialogRef不存在，无法关闭对话框')
          }
        "
        :disabled="loading"
      />
      <Button :label="$t('assistant.save')" severity="primary" @click="saveSettings" :loading="loading" :disabled="loading" />
      <Button label="保存到智能体" icon="pi pi-save" severity="primary" @click="saveToAgent" :loading="loading" :disabled="loading" />
    </div>
  </div>
</template>

<style scoped>
.assistant-manager {
  display: flex;
  flex-direction: column;
  height: 75vh;
  max-height: 600px;
  overflow: hidden;
}

.form-container {
  padding: 1rem;
  width: 100%;
}

/* 知识库设置容器 */
.kb-settings-container {
  padding: 1rem;
  width: 100%;
}

/* MCP设置容器 */
.mcp-settings-container {
  padding: 1rem;
  width: 100%;
}

/* 为知识库组件添加样式 */
.kb-settings-container :deep(.tabs-item) {
  position: static;
  width: 100%;
  left: 0;
  height: auto;
}

.actions-container {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 1rem;
  border-top: 1px solid #e5e7eb;
  background-color: white;
}

.actions-container :deep(.p-button) {
  min-width: 120px;
}

/* 头像选择器样式 */
.avatar-selector {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 15px;
}

.avatar-option {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  overflow: hidden;
  cursor: pointer;
  border: 3px solid transparent;
  transition: all 0.2s ease;
}

.avatar-option:hover {
  transform: scale(1.05);
}

.avatar-option.selected {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.25);
}

.avatar-option img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* TabView相关样式 */
:deep(.p-tabview) {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

:deep(.p-tabview-panels) {
  flex: 1;
  overflow: hidden;
}

:deep(.p-tabview-panel) {
  height: 100%;
  overflow-y: auto;
  padding: 0;
}
</style>
