<script setup>
import Icon from '@/components/Icon.vue'
import usePluginsStore from '@/stores/plugins'
import { useConfirm } from 'primevue/useconfirm'
import { i18nRender } from '@/locales'

const confirm = useConfirm()

const PluginStore = usePluginsStore()

const pluginList = computed(() => PluginStore.pluginList)

async function changePluginStatus(plugin, status, evt) {
  console.log(evt.currentTarget)

  if (status && !pluginList.value.every((item) => !item.session_status)) {
    confirm.require({
      target: evt.currentTarget,
      message: i18nRender('lang.pluginActiveTip'),
      icon: 'pi pi-exclamation-triangle',
      rejectClass: 'p-button-secondary p-button-outlined p-button-sm',
      acceptClass: 'p-button-sm',
      accept: async () => {
        await PluginStore.changePluginStatus(plugin, status)
        await PluginStore.getSessionPluginList()
      },
      reject: () => {}
    })
  } else {
    await PluginStore.changePluginStatus(plugin, status)
    await PluginStore.getSessionPluginList()
  }
}

const emits = defineEmits(['exportMessage'])

function exportMessage() {
  emits('exportMessage')
}

PluginStore.getSessionPluginList()
</script>

<template>
  <div class="flex justify-between items-center w-full h-12 py-2 px-4">
    <div class="plugins flex items-center h-full gap-2">
      <button
        v-for="item in pluginList"
        :key="item.id"
        class="text-xl bg-transparent hover:bg-blue-100 hover:bg-opacity-50 dark:hover:bg-slate-700 p-2 rounded flex items-center justify-center border-none"
        :class="!item.session_status ? 'text-slate-500' : 'text-blue-400'"
        @click="changePluginStatus(item, !item.session_status, $event)"
        v-tooltip.top="item.plugin_name"
        type="button"
      >
        <Icon :icon="item.plugin_logo" />
      </button>
    </div>
    <div class="tools">
      <div class="export-btn">
        <Button
          class="text-xl"
          size="large"
          icon="pi pi-file-export"
          text
          rounded
          v-tooltip.top="$t('lang.exportMessages')"
          @click="exportMessage"
        ></Button>
      </div>
    </div>
  </div>
</template>

<style scoped lang="scss"></style>
