<script setup>
defineProps({
  modelValue: {
    type: String,
    default: ''
  },
  config: {
    type: Object,
    default: () => ({})
  }
})

const emits = defineEmits(['update:modelValue'])

function change(value) {
  emits('update:modelValue', value)
}
</script>

<template>
  <Textarea :autoresize="false" :modelValue="modelValue" @update:modelValue="change" :maxlength="config.arg_maxlen || 500" />
</template>

<style scoped lang="scss"></style>
