<script setup>
defineProps({
  modelValue: {
    type: String,
    default: 'False'
  },
  config: {
    type: Object,
    default: () => ({})
  }
})
const emits = defineEmits(['update:modelValue'])

function change(value) {
  emits('update:modelValue', value)
}
</script>

<template>
  <InputSwitch :modelValue="modelValue" trueValue="True" falseValue="False" @update:modelValue="change" />
</template>

<style scoped lang="scss"></style>
