async function getMessages(session_id = currentConversationId.value) {
  return await getMessagesByConversionId({ session_id }).then((res) => {
    return res.resData
      .map((item) => ({
        id: item.id,
        question_id: item.question_id,
        conversation_id: item.session_id,
        sender: item.role, // user system
        content: item.text,
        think: item.think_text,
        think_cost: item.think_cost,
        time: item.create_time,
        refs: item.refs || [],
        recommend_question: item.recommend_question || [],
        feedback: item.like_type || 0,
        model_pic: item.model_pic
      }))
      .reduce((acc, cur) => {
        if (cur.sender === 'user') {
          acc.push({ question_id: cur.question_id, sender: 'user', content: [cur] })
        } else {
          const index = acc.findIndex((item) => item.question_id === cur.question_id && item.sender === 'system')
          if (index > -1) {
            acc[index].content.push(cur)
          } else {
            acc.push({ question_id: cur.question_id, sender: 'system', content: [cur] })
          }
        }
        return acc
      }, [])
