function addMessage(message) {
  console.log('addMessage')
  const length = messages.value.length
  console.log('messages.value[length - 1]?.isLoading', messages.value[length - 1]?.isLoading)
  if (messages.value[length - 1]?.isLoading) {
    console.log('isLoading', message, messages.value[length - 1])
    if (!messages.value[length - 1].content?.length) {
      messages.value[length - 1] = {
        sender: message.sender || '',
        question_id: message.question_id || '',
        content: [
          Object.assign({}, message, {
            time: new Date().getTime()
          })
        ]
      }
      console.log(messages.value[length - 1])
    }
  } else {
    messages.value.push({
      sender: message.sender || '',
      question_id: message.question_id || '',
      content: [
        Object.assign({}, message, {
          time: new Date().getTime()
        })
      ]
    })
  }
  console.log('messages.value[length - 1]', messages.value[length - 1])
  return message.id
}

function updateMessage(messageId, question_id, { ...data }) {
  const index = messages.value.findIndex((item) => item.question_id === question_id && item.sender === 'system')
  console.log('index', index)
  if (index > -1) {
    console.log('messages.value[index].content', messages.value[index].content)
    const contentIndex = messages.value[index].content.findIndex((item) => item.id === messageId)
    messages.value[index].content[contentIndex] = Object.assign(messages.value[index].content[contentIndex], data)
  } else {
    messages.value.push({
      sender: 'system',
      question_id,
      content: [data]
    })
  }
  if (messages.value[index - 1] && !messages.value[index - 1].question_id) {
    messages.value[index - 1].question_id = question_id
  }
}

