function fetchResult(params) {
  return new Promise(() => {
    controller = new AbortController()
    useSSE('/chat/sse/subscribe', {
      signal: controller.signal,
      // params: Object.assign({}, params, toRaw(modelParams)),
      params,
      onmessage: async (ev) => {
        if (status.value === 'STOPPED') {
          // 用户手动停止
          return
        }
        const isNewChat = !responseId
        try {
          if (!ev.data) {
            return
          }
          const res = JSON.parse(ev.data)
          const { flag, resData } = res
          console.log(resData)
          if (flag) {
            const { message, finish_flag, id, question_id, model_pic, think_text, think_cost } = resData
            if (!finish_flag) {
              responseId = id
            }
            const refs = resData.refs || []
            const recommend_question = resData.recommend_question || []
            tokenSpeed.value = resData.tokens || 0
            // 构建result对象
            const result = {
              conversation_id: currentConversationId.value,
              sender: 'system',
              id,
              question_id: question_id,
              content: message,
              think: think_text,
              think_cost: think_cost,
              feedback: 0, // 默认无反馈
              refs,
              model_pic: model_pic,
              recommend_question
            }
            if (isNewChat) {
              addMessage(result)
              updatingMessageId.value = id
              // updatingMessageId.value = await addMessage(result)
            } else {
              updateMessage(updatingMessageId.value, question_id, {
                content: message,
                think: think_text,
                think_cost: think_cost,
                refs,
                recommend_question,
                id
              })
            }
            // messages.value = await getMessagesByConversionId(currentConversationId.value)
            console.log('messages.value', messages.value)
            messages.value[messages.value.length - 1].typing = !finish_flag
            scrollToBottom()
            if (finish_flag) {
              ChatStore.getConversationList() // 更新conversationList
              status.value = 'FINISHED'
              responseId = ''
            }
          }
        } catch (error) {
          console.error(error)
        }
      },
      onerror(err) {
        const result = {
          conversation_id: currentConversationId.value,
          sender: 'BOT',
          content: 'ERROR'
        }
        addMessage(result)
        status.value = 'FINISHED'
        throw new Error(err)
      }
    })
  })
}

const AUTO_RENAME_LETTER_COUNT = 15

// 发送消息时自动重命名对话名称
function autoRenameConversation(id, name) {
  editConversationName(id, name)
}

// 发送消息
async function sendMessage() {
  if (!message.value) return
  status.value = 'LOADING'

  // 创建message记录
  const msgItem = {
    conversation_id: currentConversationId.value,
    sender: 'user',
    content: message.value
  }

  // 插入message
  addMessage(msgItem)

  // 确保知识库数据已加载
  if (assistantInfo.value && assistantInfo.value.kb && PluginStore.getLocalPluginStatus('retrievers')) {
    console.log('发送消息前检查知识库数据，助手配置的kb:', assistantInfo.value.kb)

    // 如果知识库数据未加载，先加载知识库数据
    if (!kbStore.selectedKb.value || !kbStore.selectedKb.value.id) {
      await getKnowledgeList({
        name: '',
        page: 1,
        pagesize: 999999
      })
        .then((res) => {
          const result = res.resData
          if (result && result.data) {
            const kbList = result.data
            // 查找匹配的知识库
            const selectedKb = kbList.find((kb) => kb.id === assistantInfo.value.kb)
            if (selectedKb) {
              // 将知识库数据设置到store中
              kbStore.setKbdata(selectedKb)
            } else {
              console.log('发送消息前未找到匹配的知识库数据，kb ID:', assistantInfo.value.kb)
            }
          }
        })
        .catch((error) => {
          console.error('发送消息前获取知识库列表失败:', error)
        })
    }
  }

  // 知识库参数
  const kbData = PluginStore.getLocalPluginStatus('retrievers') ? kbStore.getKbData() || {} : {}
  const fileData = PluginStore.getLocalPluginStatus('chat_files_retrievers')
    ? { file: kbStore.getChatFileData(), knowledge_id: ChatStore.currentConversationId }
    : {}

  const params = {
    message: message.value,
    session_id: currentConversationId.value,
    model_id: selectedModel.value,
    reference_info: {
      model_precise: ModelStore.loadedModel?.precise_load,
      ...kbData,
      ...fileData
    }
  }

  const isFirstMessage = messages.value.length === 1
  if (isFirstMessage && !assistantInfo.value) {
    autoRenameConversation(currentConversationId.value, message.value.substring(0, AUTO_RENAME_LETTER_COUNT))
  }

  // 清空输入框
  message.value = ''

  messages.value.push({
    isLoading: true,
    sender: 'system'
  })
  scrollToBottom()
  await fetchResult(params)
}

const regeneratingQuestionId = ref('')
const regeneratingMessageId = ref('')

async function regenerate(questionId) {
  status.value = 'LOADING'
  console.log(questionId)

  let index = messages.value.findIndex((item) => item.question_id === questionId && item.sender === 'system')
  const msgItem = {
    content: '',
    sender: 'system',
    conversation_id: currentConversationId.value
  }
  if (index === -1) {
    const index = messages.value.findIndex((item) => item.question_id === questionId)
    messages.value.splice(index + 1, 0, {
      sender: 'system',
      isLoading: false,
      question_id: questionId,
      content: [
        {
          conversation_id: currentConversationId.value,
          sender: 'system',
          id: '',
          question_id: questionId,
          content: '',
          feedback: 0, // 默认无反馈
          refs: [],
          recommend_question: []
        }
      ]
    })
  }
  const _index = messages.value.findIndex((item) => item.question_id === questionId && item.sender === 'system')
  console.log(_index)
  messages.value[_index].isLoading = true
  if (index > -1) {
    messages.value[index].content.push(msgItem)
  }

  controller = new AbortController()
  await useSSE('/chat/sse/re-subscribe', {
    signal: controller.signal,
    params: {
      question_id: questionId
    },
    onmessage: async (ev) => {
      if (status.value === 'STOPPED') {
        // 用户手动停止
        return
      }
      const isNewMessage = !regeneratingMessageId.value
      try {
        if (!ev.data) {
          return
        }
        const res = JSON.parse(ev.data)
        const { flag, resData } = res
        console.log('res', resData)
        if (flag) {
          const { message, finish_flag, id, question_id, think_text, think_cost } = resData
          if (!finish_flag) {
            console.log('question_id', question_id)
            regeneratingQuestionId.value = question_id
            regeneratingMessageId.value = id
          }
          const refs = resData.refs || []
          const recommend_question = resData.recommend_question || []
          tokenSpeed.value = resData.tokens || 0
          const result = {
            conversation_id: currentConversationId.value,
            sender: 'system',
            id,
            question_id: question_id,
            content: message,
            think: think_text,
            think_cost: think_cost,
            feedback: 0, // 默认无反馈
            refs,
            recommend_question
          }
          console.log('isNewMessage', isNewMessage)
          if (isNewMessage) {
            console.log('regeneratingQuestionId.value', regeneratingQuestionId.value)
            const index = messages.value.findIndex((item) => item.question_id === regeneratingQuestionId.value && item.sender === 'system')
            console.log('new index', index)
            const messageLength = messages.value[index].content.length
            messages.value[index].content[messageLength - 1] = Object.assign({}, result, {
              time: new Date().getTime()
            })
            messages.value[index].isLoading = false
            console.log(messages.value[index].isLoading)
            updatingMessageId.value = id
          } else {
            updateMessage(updatingMessageId.value, question_id, {
              content: message,
              think: think_text,
              think_cost: think_cost,
              refs,
              recommend_question,
              id
            })
          }
          messages.value[messages.value.length - 1].typing = !finish_flag
          if (finish_flag) {
            ChatStore.getConversationList() // 更新conversationList
            status.value = 'FINISHED'
            regeneratingQuestionId.value = ''
            regeneratingMessageId.value = ''
          }
          // scrollToBottom()
        }
      } catch (error) {
        console.error(error)
      }
    }
  })
}

async function stopTyping() {
  // 通知后台停止推理
  if (responseId) {
    await abortRequest(responseId)
    responseId = ''
  }
  controller && controller.abort()
  status.value = 'STOPPED'
  scrollToBottom()
}

