// 更新回馈信息
async function sendFeedback(messageId, questionId, feedback) {
  function removeIdSuffix(id = '') {
    return id.replace(new RegExp('__bot', 'g'), '').replace(new RegExp('__user', 'g'), '')
  }

  const currentFeedback =
    messages.value.find((item) => item.question_id === questionId && item.sender === 'system').content.find((item) => item.id === messageId)
      .feedback || 0
  console.log('currentFeedback', currentFeedback)
  if (currentFeedback === feedback) {
    feedback = 0
  }
  updateMessage(messageId, questionId, { feedback })
  await messageFeedback({ id: removeIdSuffix(messageId), like_type: feedback })
  messages.value = await getMessages()
}

