async function exportMessage() {
  try {
    const res = await exportChats({ session_id: currentConversationId.value })

    const contentDisposition = res.headers['content-disposition']
    let filename = 'default-filename.md'
    if (contentDisposition) {
      const filenameMatch = contentDisposition.match(/filename\*=[^'']+''(.+)/)
      if (filenameMatch && filenameMatch.length > 1) {
        filename = decodeURIComponent(filenameMatch[1])
      }
    }

    const uint8arr = new Uint8Array(res.data)
    const success = await window.pywebview.api.save_blob_file(filename, Array.from(uint8arr))

    if (!success) {
      console.warn('用户取消了保存文件')
    }
  } catch (error) {
    console.error('导出失败:', error)
    throw error
  }
}

const busEditConversationName = ({ id, name }) => editConversationName(id, name)

onMounted(() => {
  bus.on('conversation:change', changeConversation)
  bus.on('conversation:create', createConversation)
  bus.on('conversation:rename', busEditConversationName)
  bus.on('conversation:delete', deleteConversation)

  // 添加会话助手更新事件监听
  bus.on('assistant:update', (data) => {
    const { assistantId, updateVal } = data
    updateAssistant(assistantId, updateVal)
  })
})

onBeforeUnmount(() => {
  bus.off('conversation:change', changeConversation)
  bus.off('conversation:create', createConversation)
  bus.off('conversation:rename', busEditConversationName)
  bus.off('conversation:delete', deleteConversation)

  // 移除会话助手更新事件监听
  bus.off('assistant:update')
})

function copyMessage(_message) {
  message.value = _message
}

// 打开会话助手管理器
function openAssistantManager() {
  console.log('打开会话助手管理器, 当前会话助手信息:', assistantInfo.value)

  if (!assistantInfo.value || !assistantInfo.value.id) {
    console.error('无法编辑会话助手: 缺少有效的会话助手ID')
    toast.add({
      severity: 'error',
      summary: i18nRender('assistant.error'),
      detail: i18nRender('assistant.missingName'),
      life: 3000
    })
    return
  }

  dialog.open(AssistantManager, {
    props: {
      header: i18nRender('assistant.settings'),
      modal: true,
      style: {
        width: '600px'
      }
    },
    data: {
      assistant: assistantInfo.value,
      isEdit: true
    },
    onClose: () => {
      // 重新获取会话助手信息
      if (currentConversationId.value) {
        AgentStore.fetchAssistant(currentConversationId.value).then((assistant) => {
          if (assistant) {
            console.log('Dialog关闭后获取到的会话助手信息:', assistant)
            assistantInfo.value = assistant
            recommendedQuestions.value = assistant.recommended_questions || []
          }
        })
      }
    }
  })
}

// 使用推荐问题
function useRecommendedQuestion(question) {
  message.value = question
}

// 更新会话助手设置
async function updateAssistant(assistantId, updateVal) {
  try {
    console.log('事件总线接收到会话助手更新请求:', { assistantId, updateVal })
    console.log('当前会话ID:', currentConversationId.value)
    console.log('updateVal是否有效:', updateVal !== undefined)

    if (!updateVal) {
      console.error('updateVal数据为空，终止更新操作')
      return
    }

    // 更新当前会话的会话助手设置
    await AgentStore.updateAssistant(currentConversationId.value, updateVal)

    // 刷新会话助手信息
    const assistant = await AgentStore.fetchAssistant(currentConversationId.value)
    if (assistant) {
      assistantInfo.value = assistant
      recommendedQuestions.value = assistant.recommended_questions || '[]'

      // 会话变更的watch函数会自动处理知识库数据的加载，这里不需要重复
      // console.log('更新会话助手设置完成，更新后的助手数据:', assistant)
    }
  } catch (error) {
    console.error('更新会话助手设置失败:', error)
    toast.add({
      severity: 'error',
      summary: i18nRender('assistant.error'),
      detail: error.message || i18nRender('assistant.error'),
      life: 3000
    })
  }
}

// 监听会话变化，更新智能体信息
watch(
  () => currentConversationId.value,
  async (value) => {
    if (value) {
      const assistant = await AgentStore.fetchAssistant(value)
      if (assistant) {
        assistantInfo.value = assistant
        recommendedQuestions.value = assistant.recommended_questions || '[]'

        // 如果助手设置了知识库，则加载知识库数据
        if (assistant.kb) {
          // 获取知识库数据列表
          try {
            const kbResponse = await getKnowledgeList({
              name: '',
              page: 1,
              pagesize: 999999
            })

            const result = kbResponse.resData
            if (result && result.data) {
              const kbList = result.data

              // 查找匹配的知识库
              const selectedKb = kbList.find((kb) => kb.id === assistant.kb)
              if (selectedKb) {
                // 将知识库数据设置到store中
                kbStore.setKbdata(selectedKb)

                // 确保知识库插件已启用
                if (!PluginStore.getLocalPluginStatus('retrievers')) {
                  const pluginList = PluginStore.pluginList
                  const knowledgePlugin = pluginList.find((plugin) => plugin.plugin_key === 'retrievers')
                  if (knowledgePlugin) {
                    await PluginStore.changePluginStatus(knowledgePlugin, true)
                    await PluginStore.getSessionPluginList()
                  }
                } else {
                  // console.log('会话变更，知识库插件已启用')
                }
              } else {
                // console.log('会话变更，未找到匹配的知识库数据，kb ID:', assistant.kb)
              }
            } else {
              // console.log('会话变更，知识库列表为空')
            }
          } catch (error) {
            console.error('会话变更，获取知识库列表失败:', error)
          }
        } else {
          // console.log('会话变更，助手未配置知识库')
        }
      } else {
        assistantInfo.value = null
        recommendedQuestions.value = []
      }
    }
  },
  { immediate: true }
)

function getVersion() {
  return service_getVersion().then((res) => {
    version.value = res.resData
  })
}

const version = ref('-')
getVersion()
</script>

