<script setup>
defineProps({
  modelValue: {
    type: Number,
    default: 0
  },
  config: {
    type: Object,
    default: () => ({})
  }
})

const emits = defineEmits(['update:modelValue'])

function change(value) {
  emits('update:modelValue', value)
}

function getPrecision(precision = 0) {
  return 1 / Math.pow(10, precision)
}
</script>

<template>
  <Slider
    :modelValue="modelValue"
    @update:modelValue="change"
    class="w-full grow shrink"
    :step="getPrecision(config.arg_precision)"
    :min="config.arg_min || 0"
    :max="config.arg_max || 8000"
  ></Slider>
  <InputNumber
    class="w-20 grow-0 shrink-0 border-clear-deep"
    :inputStyle="{ width: '100%', textAlign: 'center' }"
    :modelValue="modelValue"
    @update:modelValue="change"
    :useGrouping="false"
    :step="getPrecision(config.arg_precision)"
    :min="config.arg_min || 0"
    :max="config.arg_max || 8000"
  />
</template>

<style scoped lang="scss"></style>
