<script setup>
defineProps({
  modelValue: {
    type: String,
    default: ''
  },
  config: {
    type: Object,
    default: () => ({})
  }
})

const emits = defineEmits(['update:modelValue'])

function change(value) {
  emits('update:modelValue', value)
}
</script>

<template>
  <InputText :modelValue="modelValue" @update:modelValue="change" />
</template>

<style scoped lang="scss"></style>
