<script setup>
import { OpenChat } from './disclaimer'
import useAppStore from '@/stores/app'

const app = useAppStore()
const language = app.getLanguage()
const visible = ref(false)
const title = ref('')
const content = ref('')

const emits = defineEmits(['close'])

function show(type) {
  visible.value = true
  if (type === 'OpenChat') {
    title.value = language === 'zh-CN' ? OpenChat.titleCN : OpenChat.titleEN
    content.value = language === 'zh-CN' ? OpenChat.cn : OpenChat.en
  }
}

function close() {
  visible.value = false
  emits('close')
}
defineExpose({ show })
</script>
<template>
  <Dialog v-model:visible="visible" @hide="close" :closable="false" :closeOnEscape="false" style="width: 50vw">
    <div v-html="content"></div>
    <template #footer>
      <Button @click="close" :label="$t('lang.confirm')"></Button>
    </template>
  </Dialog>
</template>
<style lang="scss" scoped></style>
