<script setup>
import dayjs from 'dayjs'
import Markdown from './Markdown.vue'
import Loading from '@/views/chat/components/Loading.vue'
import useModelStore from '@/stores/models'
import { copy } from '../../../utils/util'
import { useConfirm } from 'primevue/useconfirm'
import { useWebview } from '@/composables/useWebview'

const { copyText, openExternalLink } = useWebview()
const confirm = useConfirm()

const ModelStore = useModelStore()

const props = defineProps({
  sender: {
    default: '',
    type: String
  },
  content: {
    default: () => [],
    type: Array
  },
  // time: {
  //   default: 0,
  //   type: Number
  // },
  isLoading: {
    type: Boolean,
    default: false
  },
  typing: {
    type: Boolean,
    default: false
  },
  // refs: {
  //   type: Array,
  //   default: () => [
  //     {
  //       url: 'xxx',
  //       text: '你好，很高兴在这里回答你的问题:September的缩写是Sep.九月.全文.以上回答不满意?免费领取专业答主针对性解答,匹配到多家专业机构为你服务.您的电话 你好，很高兴在这里回答你的问题:September的缩写是Sep.九月.全文.以上回答不满意?免费领取专业答主针对性解答,匹配到多家专业机构为你服务.您的电话 ',
  //       title: 'title title title title title title title title title title title title title title title title'
  //     },
  //     { url: 'xxx', text: 'text', title: 'title' },
  //     { url: 'xxx', text: 'text', title: 'title' },
  //     { url: 'xxx', text: 'text', title: 'title' }
  //   ]
  // },
  // recommend_question: {
  //   type: Array,
  //   default: () => [
  //     { url: 'xxx', question: 'Python中的SEP是什么意思?' },
  //     { url: 'xxx', question: 'Python中的SEP是什么意思?' },
  //     { url: 'xxx', question: 'Python中的SEP是什么意思?' },
  //     { url: 'xxx', question: 'Python中的SEP是什么意思?' }
  //   ]
  // },
  // id: {
  //   type: [Number, String],
  //   default: ''
  // },
  questionId: {
    type: [Number, String],
    default: ''
  }
  // feedback: {
  //   type: Number,
  //   default: 0
  // }
})

const emits = defineEmits(['sendFeedback', 'useRecommend', 'deleteChatItem', 'regenerate'])

function sendFeedback(feedback, id) {
  emits('sendFeedback', id, props.questionId, feedback)
}

function useRecommend(content) {
  emits('useRecommend', content)
}

function regenerate() {
  emits('regenerate', props.questionId)
}

function deleteChatItem(event) {
  console.log('deleteChatItem', props.questionId)
  confirm.require({
    target: event.currentTarget,
    message: '确定删除该条目吗?',
    icon: 'pi pi-info-circle',
    rejectClass: 'p-button-secondary p-button-outlined p-button-sm',
    acceptClass: 'p-button-danger p-button-sm',
    rejectLabel: '取消',
    acceptLabel: '删除',
    accept: () => {
      emits('deleteChatItem', props.questionId)
    }
  })
}
const activeIndex = ref(Math.max(props.content.length - 1, 0))
const activeItem = computed(() => props.content[activeIndex.value] || {})

function prevActive() {
  console.log(activeIndex.value, Math.max(0, activeIndex.value - 1))
  activeIndex.value = Math.max(0, activeIndex.value - 1)
}

function nextActive() {
  const length = props.content.length
  activeIndex.value = Math.min(length - 1, activeIndex.value + 1)
}

watch(
  () => props.content.length,
  (value) => {
    activeIndex.value = value - 1
  }
)

const DEFAULT_AVATAR =
  ''

const deepThinkOpen = ref(true)

function changeDeepThinkOpen() {
  deepThinkOpen.value = !deepThinkOpen.value
}

const copySuccess = ref(false)

function copyChatItem(item, fallback = false) {
  if (item.content) {
    copyText(item.content) // ✅ 使用你封装好的跨平台复制方法

    if (fallback) {
      emits('copyMessage', item.content) // ✅ 可选：通知父组件
    }

    copySuccess.value = true
    setTimeout(() => {
      copySuccess.value = false
    }, 2000)
  }
}
</script>

<template>
  <div
    class="group/chat pb-8 relative w-full flex items-start gap-4 justify-start"
    :class="sender !== 'user' ? ['flex-row'] : ['flex-row-reverse']"
  >
    <div class="avatar mt-8" :class="sender !== 'user' ? ['self-start'] : ['self-end']">
      <Avatar
        class="overflow-hidden"
        size="large"
        v-if="sender === 'system'"
        :image="activeItem?.model_pic || ModelStore.loadedModel?.model_pic || DEFAULT_AVATAR"
      ></Avatar>
      <Avatar size="large" v-else icon="pi pi-user"></Avatar>
    </div>
    <div class="absolute top-1 flex flex-row items-center justify-start text-slate-500 gap-1" v-if="content.length > 1">
      <i class="cursor-pointer pi pi-angle-left" @click="prevActive"></i>
      <span class="text-slate-700">{{ activeIndex + 1 }}</span>
      <i class="cursor-pointer pi pi-angle-right" @click="nextActive"></i>
    </div>
    <div
      class="chat_item min-w-[40%] p-4 rounded-2xl max-w-[75%] relative pb-8 mt-8"
      :class="
        sender !== 'user'
          ? ['rounded-tl', 'bg-white dark:bg-slate-900', 'text-slate-800 dark:text-slate-200']
          : ['rounded-br', 'bg-blue-500 dark:bg-blue-300', 'text-white dark:text-black']
      "
    >
      <div class="content leading-6 tracking-wider">
        <Loading v-if="isLoading"></Loading>
        <!--        <i  class="pi pi-spin pi-spinner" style="font-size: 2rem"></i>-->
        <template v-else>
          <template v-if="sender === 'system'">
            <div class="border-clear border-l-2 border-solid border-zinc-300 mb-4 pl-3 text-md" v-if="activeItem?.think">
              <div
                class="mb-2 text-slate-500 dark:text-slate-200 flex items-center justify-start gap-2 cursor-pointer"
                @click="changeDeepThinkOpen"
              >
                <span style="font-size: 1rem">
                  深度思考 <i v-if="!activeItem?.content" class="pi pi-spin pi-spinner" style="font-size: 1rem"></i>
                </span>
                <Icon class="text-xs" :icon="deepThinkOpen ? 'pi pi-angle-up' : 'pi pi-angle-down'"></Icon>
              </div>

              <div
                class="text-slate-400 dark:text-slate-300 grid overflow-hidden transition-all duration-300 ease-in-out"
                :class="deepThinkOpen ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]'"
              >
                <div class="min-h-0">
                  <Markdown :content="activeItem?.think"></Markdown>
                </div>
              </div>
            </div>

            <Markdown :content="activeItem?.content || ''" />
          </template>
          <template v-else-if="sender === 'user'">
            <div class="break-words overflow-x-auto">{{ activeItem?.content }}</div>
          </template>
        </template>
      </div>
      <div v-if="sender === 'system'" class="resource">
        <template v-if="!typing && activeItem?.refs && activeItem?.refs.length">
          <Divider align="left" class="">
            <span class="text-normal text-slate-600 font-bold">{{ $t('lang.sources') }}</span>
          </Divider>
          <div class="source_list grid grid-cols-4 gap-4">
            <a v-for="item in activeItem?.refs || []" class="cursor-pointer block" :href="item.url" :key="item.url" target="_blank">
              <Card
                class="bg-slate-200 dark:bg-slate-800 hover:bg-slate-300 dark:hover:bg-slate-700 shadow-none h-18 rounded-lg"
                :pt="{ root: { class: 'border-none h-full' }, body: { class: 'pt-2 px-2 pb-1.5 h-full' } }"
              >
                <template #content>
                  <div class="flex flex-col justify-between h-full">
                    <div
                      class="text-neutral-800 dark:text-slate-200 text-xs leading-4 tracking-wider line-clamp-2 min-h-[2rem] flex-shrink-0 overflow-hidden mb-1.5"
                    >
                      {{ item.title }}
                    </div>
                    <div class="flex items-center space-x-1 flex-shrink-0">
                      <img
                        v-if="item.site_icon && item.site_icon !== 'None'"
                        :src="item.site_icon"
                        class="w-3 h-3 object-contain"
                        @error="$event.target.outerHTML = '<i class=\'pi pi-link text-slate-500\' style=\'font-size: 0.75rem\'></i>'"
                      />
                      <i v-else class="pi pi-link text-slate-500" style="font-size: 0.75rem"></i>
                      <span class="text-xs leading-5 tracking-wider text-slate-500 truncate">{{ item.site_name || '网页搜索' }}</span>
                    </div>
                  </div>
                </template>
              </Card>
            </a>
          </div>
        </template>
        <!-- <template v-if="!typing && activeItem?.recommend_question && activeItem?.recommend_question.length">
          <Divider align="left" class="">
            <span class="text-xs text-slate-400">{{ $t('lang.related') }}</span>
          </Divider>
          <div class="source_list flex flex-row flex-wrap gap-4 items-center justify-start">
            <div
              v-for="item in activeItem?.recommend_question || []"
              :key="item.question"
              class="cursor-pointer"
              @click="useRecommend(item.question)"
            >
              <Card class="bg-blue-200 dark:bg-blue-600 bg-opacity-30 h-full hover:bg-opacity-50" :pt="{ body: { class: 'py-2 px-4' } }">
                <template #content>
                  <div class="text-wrap text-sm text-slate-500 dark:text-slate-200 truncate">
                    {{ item.question }}
                  </div>
                </template>
              </Card>
            </div>
          </div>
        </template> -->
      </div>
      <div
        v-if="!!activeItem?.time"
        class="time absolute right-4 bottom-1 text-sm font-semibold"
        :class="sender === 'system' ? ['text-slate-400'] : ['text-slate-200 dark:text-slate-700']"
      >
        {{ dayjs(activeItem?.time).format('HH:mm') }}
      </div>
      <div v-if="sender === 'system'" class="absolute -bottom-8 right-4 text-slate-900 space-x-4">
        <i
          @click="sendFeedback(1, activeItem?.id)"
          style="font-size: 1rem"
          class="group-hover/chat:inline pi cursor-pointer"
          :class="[
            activeItem?.feedback === 1 ? 'pi pi-thumbs-up-fill text-blue-500' : 'pi-thumbs-up',
            activeItem?.feedback !== 0 ? 'inline' : 'hidden'
          ]"
        ></i>
        <i
          @click="sendFeedback(2, activeItem?.id)"
          style="font-size: 1rem"
          class="group-hover/chat:inline pi cursor-pointer"
          :class="[
            activeItem?.feedback === 2 ? 'pi pi-thumbs-down-fill text-red-500' : 'pi-thumbs-down',
            activeItem?.feedback !== 0 ? 'inline' : 'hidden'
          ]"
        ></i>
      </div>
      <div class="absolute -bottom-8 left-4 text-slate-900 space-x-4">
        <i
          v-if="sender === 'user'"
          @click="regenerate"
          style="font-size: 1rem"
          class="group-hover/chat:inline hidden text-primary-500 pi pi-sync cursor-pointer"
        ></i>
        <button
          v-if="sender === 'user'"
          @click="deleteChatItem"
          class="group-hover/chat:inline hidden bg-transparent border-none p-0"
          aria-label="删除"
        >
          <i style="font-size: 1rem" class="text-orange-600 pi pi-trash cursor-pointer"></i>
        </button>
        <i
          @click="copyChatItem(activeItem, sender === 'user')"
          style="font-size: 1rem"
          class="group-hover/chat:inline hidden cursor-pointer"
          :class="!copySuccess ? 'pi pi-copy' : 'pi pi-check'"
        ></i>
      </div>
    </div>
  </div>
</template>

<style scoped lang="scss"></style>
